// AiXenix Cosmos Lab web client: React host for the 3D view. Frames are pushed imperatively from a source (one snapshot
// per render), so playback does not re-render React.

import { useEffect, useRef, useState } from 'react';
import { SpaceView, webglAvailable, type Framing, type SceneCameraHint, type ViewFrame, type ViewOptions } from '../render/SpaceView';
import { settingsStore, useT } from '../app/settings';
import { useStore } from '../app/store';

export interface FrameSource {
  get(): ViewFrame | null;
  subscribe(listener: () => void): () => void;
}

export interface CameraRequest {
  serial: number;
  id: number | null;
  /** Focus by scene key instead of id (resolved against the frame being shown). */
  key?: string;
  fit: boolean;
  hint?: SceneCameraHint;
  framing?: Framing;
  animate?: boolean;
}

export function Viewport({
  source,
  interactive,
  autoRotate = false,
  camera,
  onPick,
  onFocus,
  onGridScale,
  className,
  overrides,
}: {
  source: FrameSource;
  interactive: boolean;
  autoRotate?: boolean;
  camera?: CameraRequest;
  onPick?: (id: number | null) => void;
  onFocus?: (id: number) => void;
  onGridScale?: (metres: number) => void;
  className?: string;
  overrides?: Partial<ViewOptions>;
}) {
  const t = useT();
  const host = useRef<HTMLDivElement>(null);
  const view = useRef<SpaceView | null>(null);
  const handlers = useRef({ onPick, onFocus, onGridScale });
  handlers.current = { onPick, onFocus, onGridScale };
  const cameraRef = useRef(camera);
  cameraRef.current = camera;
  const [failed, setFailed] = useState(false);
  const settings = useStore(settingsStore, (s) => s);

  const options = (): ViewOptions => ({
    interactive,
    quality: settings.quality,
    bloom: settings.bloom,
    showLabels: settings.showLabels,
    showOrbits: settings.showOrbits,
    showTrails: settings.showTrails,
    showGrid: settings.showGrid,
    showStars: settings.showStars,
    showTracers: settings.showTracers,
    sizeScale: settings.sizeScale,
    reducedMotion: settings.reducedMotion,
    autoRotate,
    ...overrides,
  });

  useEffect(() => {
    const el = host.current;
    if (!el) return;
    if (!webglAvailable()) {
      setFailed(true);
      return;
    }
    let v: SpaceView;
    try {
      v = new SpaceView(el, options(), {
        onPick: (id) => handlers.current.onPick?.(id),
        onFocus: (id) => handlers.current.onFocus?.(id),
        onGridScale: (m) => handlers.current.onGridScale?.(m),
      });
    } catch {
      setFailed(true);
      return;
    }
    view.current = v;
    v.setOptions(options());
    const push = () => {
      const f = source.get();
      if (f) v.setFrame(f);
    };
    push();
    // A view created after the request (e.g. a new source) still gets the current camera request.
    if (cameraRef.current) applyCamera(v, cameraRef.current);
    const unsub = source.subscribe(push);
    return () => {
      unsub();
      v.dispose();
      view.current = null;
    };
    // The view is created once per source; option changes are applied below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [source]);

  useEffect(() => {
    view.current?.setOptions(options());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings, interactive, autoRotate, overrides]);

  useEffect(() => {
    if (!camera || !view.current) return;
    const v = view.current;
    // Apply after the frame that triggered it is in place.
    const f = source.get();
    if (f) v.setFrame(f);
    applyCamera(v, camera);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [camera?.serial]);

  return (
    <div ref={host} className={'viewport' + (className ? ' ' + className : '')}>
      {failed && (
        <div className="viewport-error" role="alert">
          {t('error.webgl')}
        </div>
      )}
    </div>
  );
}

function applyCamera(v: SpaceView, camera: CameraRequest): void {
  const opts = { fit: camera.fit, hint: camera.hint, animate: camera.animate, framing: camera.framing };
  if (camera.key) v.focusOnKey(camera.key, opts);
  else v.focusOn(camera.id, opts);
}
